CREATE TABLE IF NOT EXISTS STATEMENTS (id TEXT NOT NULL, subscription_id TEXT NOT NULL, customer_id TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, issued_at TEXT NOT NULL, total_amount TEXT NOT NULL, currency TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, deleted_at TIMESTAMPTZ, PRIMARY KEY (id, period_start)) PARTITION BY RANGE (period_start); CREATE TABLE IF NOT EXISTS statements_default PARTITION OF statements DEFAULT; CREATE INDEX IF NOT EXISTS idx_statements_customer_id ON statements (customer_id); CREATE INDEX IF NOT EXISTS idx_statements_subscription_id ON statements (subscription_id);